import os
import hashlib
import hmac
import unicodedata
import re
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file, abort

app = Flask(__name__)

BASE_DIR = '/srv/shared_files'
SECRET_KEY = os.urandom(32)
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.csv', '.doc', '.docx'}
MAX_PATH_LENGTH = 255
MAX_FILE_SIZE = 50 * 1024 * 1024  # 50MB


def generate_access_token(username, filepath):
    """Generate HMAC token for file access authorization."""
    msg = f"{username}:{filepath}".encode('utf-8')
    return hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()


def verify_access_token(username, filepath, token):
    """Verify HMAC token for file access."""
    expected = generate_access_token(username, filepath)
    return hmac.compare_digest(expected, token)


def compute_file_integrity(filepath):
    """Compute SHA-256 hash for file integrity verification."""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        while chunk := f.read(8192):
            h.update(chunk)
    return h.hexdigest()


def is_path_component_safe(component):
    """Check individual path component for dangerous patterns."""
    if component in ('', '.', '..'):
        return False
    if component.startswith('.'):
        return False
    if any(c in component for c in ['\x00', '\n', '\r']):
        return False
    if len(component) > 64:
        return False
    return True


def validate_extension(filename):
    """Validate file extension against allowlist."""
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS


def sanitize_path(user_path):
    """Multi-layer path sanitization pipeline.

    Applies security checks to prevent directory traversal.
    Returns (safe_path, error) tuple.
    """
    if not user_path or len(user_path) > MAX_PATH_LENGTH:
        return None, "Invalid path length"

    # Step 1: Reject obvious traversal attempts
    if '..' in user_path or user_path.startswith('/'):
        return None, "Path traversal detected"

    # Step 2: Check for null bytes
    if '\x00' in user_path:
        return None, "Null byte in path"

    # Step 3: Reject backslashes (Windows-style paths)
    if '\\' in user_path:
        return None, "Invalid path separator"

    # Step 4: Validate each component
    components = user_path.split('/')
    for comp in components:
        if not is_path_component_safe(comp):
            return None, f"Unsafe path component: {comp}"

    # Step 5: Apply Unicode NFC normalization AFTER validation
    # This ensures consistent storage lookup
    normalized_path = unicodedata.normalize('NFC', user_path)

    # Step 6: Construct and verify final path
    final_path = os.path.join(BASE_DIR, normalized_path)

    # Step 7: Resolve to real path and verify containment
    try:
        real_path = os.path.realpath(final_path)
    except (OSError, ValueError):
        return None, "Path resolution failed"

    if not real_path.startswith(BASE_DIR):
        return None, "Path escapes base directory"

    return real_path, None


