@app.route('/api/v1/files/<path:filepath>', methods=['GET'])
def serve_file(filepath):
    """Serve a file with full security validation pipeline."""
    # Authentication
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        abort(401)

    token = auth_header[7:]
    username = request.headers.get('X-Username', '')

    if not username or not re.match(r'^[a-zA-Z0-9_]{1,32}$', username):
        abort(401)

    # Rate limiting
    if not check_rate_limit(username):
        abort(429)

    # Authorization check
    if not verify_access_token(username, filepath, token):
        abort(403)

    # Path validation and sanitization
    safe_path, error = sanitize_path(filepath)
    if error:
        return jsonify({'error': error}), 400

    # Extension validation
    if not validate_extension(safe_path):
        return jsonify({'error': 'File type not allowed'}), 403

    # File existence check
    if not os.path.isfile(safe_path):
        abort(404)

    # File size check
    file_size = os.path.getsize(safe_path)
    if file_size > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 413

    # Compute integrity hash
    integrity = compute_file_integrity(safe_path)

    response = send_file(safe_path)
    response.headers['X-Content-SHA256'] = integrity
    response.headers['X-Served-By'] = 'secure-file-server/1.0'
    return response


@app.route('/api/v1/files', methods=['POST'])
def upload_file():
    """Upload a file with security validation."""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        abort(401)

    username = request.headers.get('X-Username', '')
    if not username or not re.match(r'^[a-zA-Z0-9_]{1,32}$', username):
        abort(401)

    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    target_path = request.form.get('path', '')

    safe_path, error = sanitize_path(target_path)
    if error:
        return jsonify({'error': error}), 400

    if not validate_extension(uploaded.filename):
        return jsonify({'error': 'File type not allowed'}), 403

    # Ensure directory exists
    os.makedirs(os.path.dirname(safe_path), exist_ok=True)
    uploaded.save(safe_path)

    return jsonify({'status': 'uploaded', 'path': target_path}), 201


if __name__ == '__main__':
    os.makedirs(BASE_DIR, exist_ok=True)
    app.run(host='127.0.0.1', port=8080, debug=False)
